import threading
from collections import OrderedDict


class LRUCache:
    """Fixed-capacity cache that evicts the least recently used entry.

    Safe for concurrent use: every read is also a write (move_to_end plus a
    counter bump), so there is no read path that can skip the lock.
    """

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._entries = OrderedDict()
        self._lock = threading.Lock()
        self._hits = 0
        self._misses = 0

    def get(self, key, default=None):
        with self._lock:
            if key not in self._entries:
                self._misses += 1
                return default
            self._entries.move_to_end(key)
            self._hits += 1
            return self._entries[key]

    def put(self, key, value):
        with self._lock:
            if key in self._entries:
                self._entries.move_to_end(key)
            self._entries[key] = value
            if len(self._entries) > self.capacity:
                self._entries.popitem(last=False)

    def stats(self):
        with self._lock:
            return {
                "hits": self._hits,
                "misses": self._misses,
                "size": len(self._entries),
            }

    def __contains__(self, key):
        # membership must not count as a use, so no move_to_end here
        with self._lock:
            return key in self._entries

    def __len__(self):
        with self._lock:
            return len(self._entries)

    def clear(self):
        with self._lock:
            self._entries.clear()
            self._hits = 0
            self._misses = 0

    def __repr__(self):
        s = self.stats()
        return "LRUCache(capacity={}, size={}, hits={}, misses={})".format(
            self.capacity, s["size"], s["hits"], s["misses"]
        )
